def gyro_noise(D, N):
    """Gyro sample noise [rad/s]: standard deviation of first differences of consecutive valid raw samples / sqrt(2)."""
    s1 = 0.0; s2 = 0.0; n = 0
    for c0 in range(0, N, CH):
        c1 = min(N, c0 + CH + 1); vv = D.valid[c0:c1]; dd = np.diff(D.decode(c0, c1, "w"), axis=0)[vv[1:] & vv[:-1]]
        if len(dd): s1 += float(dd.sum()); s2 += float((dd * dd).sum()); n += dd.size
    return math.sqrt(max(s2 / n - (s1 / n) ** 2, 0.0) / 2.0) if n else float("inf")
